#!/usr/bin/env python3
"""V2-PACKED gate: one LG00-sized real packed product, its landed advice and its packed literals, emitted as
kernel probes (untrusted tooling; the kernel re-checks everything).

The product has LG00's shape (2-D Fourier keys, CertFixed 128 mantissas, the box layouts and widths of a median
cfgLow product of the LG00 L = 20 advice books) and synthetic LG00-like coefficients: every key of the box with
|k|_1 <= R, magnitude 2^(P-3) e^(-0.9 |k|_1), seeded uniform signs and sizes.

* The landed advice is generated by the landed mirror `scripts/spin_orbit/sofx_packed.py` (PackedEngine.build_real),
  and checked by its mirror of checkPackedProduct.
* The packed route: GmpSpec (same layouts and width), Za, Zb (packSum of the dense slots), R = gmpRound(Za Zb),
  the read-back terms and the a-priori remainder; the rounding shift s is the largest with remainder <= the landed
  remainder (equal or better error bound).

Writes $V2P_GATE_DIR/<TAG>*.lean (default .lake/v2-packed-gate, outside the sources; one forced theorem per file;
`run_probe.sh` runs them) and $V2P_GATE_DIR/<TAG>.json (sizes, remainders, literal bytes).
Usage: python3 -I scripts/packed/gate_gen.py [TAG] [dimsA0 dimsA1 dimsB0 dimsB1 radius]
       python3 -I scripts/packed/gate_gen.py compute        (the literal-free compute probes C19kCompute*)
"""
import json
import math
import os
import random
import sys
from fractions import Fraction as F

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, os.path.join(ROOT, "scripts", "spin_orbit"))
import sofx_packed as SP                       # noqa: E402
from sodata_packed import pack_sum             # noqa: E402

P = 128
P2 = 2 * P
CHUNK_HEX = 72                                 # hexadecimal digits per literal chunk (288 bits)
# Generated probes stay OUT of the repository: their packed literals need one 288-bit chunk per line (lines <= 100
# characters), so they exceed the 1500-line cap of repository Lean files. They are deterministic (seeded).
OUT = os.environ.get("V2P_GATE_DIR", os.path.join(ROOT, ".lake", "v2-packed-gate"))


class Weight:
    def __init__(self, rho, w):
        self.rho, self.w = rho, w


W = Weight(F(1, 100), F(107, 100))             # w >= e^(2 pi rho) = 1.0649


def gen_terms(rng, lo, dims, rad):
    out = []
    for a in range(dims[0]):
        for b in range(dims[1]):
            k = (lo[0] + a, lo[1] + b)
            d = abs(k[0]) + abs(k[1])
            if d > rad:
                continue
            v = int(round(2.0 ** (P - 3) * math.exp(-0.9 * d) * (2 * rng.random() - 1)))
            out.append((k, v if v else 1))
    return out                                  # ascending slots (row-major)


# ------------------------------------------------------------------------------------------------ packed mirror
def periodic(w, N, m):
    return m * ((2 ** (w * N) - 1) // (2 ** w - 1))


def gmp_round(w, N, l, s, Z):
    """Mirror of `gmpRound` (the Lean formula, operation by operation)."""
    Y = Z + periodic(w, N, 2 ** l + 2 ** (s - 1))
    assert Y >= 0
    Y = (Y - (Y & periodic(w, N, 2 ** s - 1))) >> s
    return Y - periodic(w, N, 2 ** (l - s))


def digit_caps(ss, N):
    out = []
    for s in ss:
        out.append((N - 1) // s)
        N = s
    return out


def deg_cap(la, lb, N):
    caps = digit_caps(list(la.stride), N)
    tot = 0
    for j in range(len(la.dims)):
        lo = la.lo[j] + lb.lo[j]
        tot += max(abs(lo), abs(lo + caps[j]))
    return tot


def gmp_rem(N, s, dcap):
    return F(N * 2 ** (s - 1)) * W.w ** dcap / 2 ** P2


# ------------------------------------------------------------------------------------------------ Lean emission
def wrap(items, indent=4, width=100):
    lines, cur = [], " " * indent
    for i, it in enumerate(items):
        piece = it + ("," if i + 1 < len(items) else "")
        if len(cur) + len(piece) + 1 > width and cur.strip():
            lines.append(cur.rstrip())
            cur = " " * indent
        cur += piece + " "
    if cur.strip():
        lines.append(cur.rstrip())
    return "\n".join(lines)


PART = 300                                     # list elements per definition (LG00's split literals)

FORMAT = """/-- Zigzag decoding (LG00's literal format: natural literals elaborate fast). -/
def dz (n : ℕ) : ℤ := if n % 2 = 0 then Int.ofNat (n / 2) else Int.negSucc (n / 2)

def dzs (l : List ℕ) : List ℤ := l.map dz

/-- A zigzag-coded term of integer Fourier data with a two-variable key. -/
abbrev tk (k₀ k₁ v : ℕ) : CertKey × ℤ := ([dz k₀, dz k₁], dz v)

"""


def zz(v):
    return 2 * v if v >= 0 else -2 * v - 1


def lean_parts(name, ty, items, wrapper):
    parts = [items[i:i + PART] for i in range(0, max(len(items), 1), PART)] if items else [[]]
    out = []
    for j, pt in enumerate(parts):
        out.append("noncomputable def %s_p%d : %s :=\n  %s[\n%s]\n" % (name, j, ty, wrapper, wrap(pt)))
    joined = " ++ ".join("%s_p%d" % (name, j) for j in range(len(parts)))
    out.append("noncomputable def %s : %s :=\n%s\n" % (name, ty, wrap(joined.split(" "), indent=2)
                                                    .replace(" ++,", " ++").replace(",", "")))
    return "".join(out)


def lean_int_list(name, xs):
    return lean_parts(name, "List ℤ", [str(zz(x)) for x in xs], "dzs ")


def lean_terms(name, ts):
    return lean_parts(name, "List (CertKey × ℤ)", ["tk %d %d %d" % (zz(k[0]), zz(k[1]), zz(v)) for k, v in ts],
                      "")


def nat_ramp(b, n):
    """Mirror of `natRamp`: Σ_{i<n} (i+1) 2^(b i)."""
    return (n * 2 ** (b * (n + 1)) + 1 - (n + 1) * 2 ** (b * n)) // (2 ** b - 1) ** 2


def nat_tree(n, masked=True):
    """A balanced `natJoin` tree of 288-bit hexadecimal chunks (one chunk per line), XOR-ed with the ramp
    `natRamp 288 m` so that no two partial results share their low 64 bits (the kernel hashes a natural literal by
    its low 64 bits). Returns the Lean expression (a natural number) and the chunk count."""
    bits = CHUNK_HEX * 4
    m = max(1, -(-n.bit_length() // bits))
    if masked:
        assert nat_ramp(bits, m) == sum((i + 1) << (bits * i) for i in range(m))
        n ^= nat_ramp(bits, m)
    chunks = [(n >> (bits * i)) & ((1 << bits) - 1) for i in range(m)]
    assert n >> (bits * m) == 0
    lines = []

    def emit(lo, hi, depth):
        ind = " " * (4 + min(depth, 6))
        if hi - lo == 1:
            lines.append(ind + "0x%X" % chunks[lo])
            return
        mid = (lo + hi) // 2
        lines.append(ind + "(natJoin %d" % (bits * (mid - lo)))
        emit(lo, mid, depth + 1)
        emit(mid, hi, depth + 1)
        lines[-1] += ")"
    emit(0, len(chunks), 0)
    out = []
    for ln in lines:                            # trailing parentheses of a deep leaf go on their own line
        core = ln.rstrip(")")
        if len(ln) > 96 and core != ln:
            out.extend([core, "    " + ")" * (len(ln) - len(core))])
        else:
            out.append(ln)
    body = "\n".join(out)
    if masked:
        body = "    ((\n%s)\n    ^^^ natRamp %d %d)" % (body, bits, m)
    return body, len(chunks)


def lean_int_big(name, z):
    body, nch = nat_tree(abs(z))
    sign = "-" if z < 0 else ""
    return "noncomputable def %s : ℤ :=\n  %s((\n%s\n    : ℕ) : ℤ)\n" % (name, sign, body), nch


def lean_layout(L):
    return "⟨[%d, %d], [%d, %d], [%d, %d], %d, %d⟩" % (L.lo[0], L.lo[1], L.dims[0], L.dims[1], L.stride[0],
                                                      L.stride[1], L.width, L.blockRows)


def lean_rat(q):
    """A rational literal; long numerators and denominators as `natJoin` trees."""
    if len(str(q.numerator)) + len(str(q.denominator)) < 60:
        return "(%d / %d : ℚ)" % (q.numerator, q.denominator)
    nb, _ = nat_tree(abs(q.numerator), masked=False)
    db, _ = nat_tree(q.denominator, masked=False)
    sign = "-" if q < 0 else ""
    return "\n  %s(((\n%s\n    : ℕ) : ℚ) /\n    ((\n%s\n    : ℕ) : ℚ))" % (sign, nb, db)


HEADER = """/-
Copyright (c) 2026 Scott Armstrong, Zohar Komargodski. All rights reserved.
Released under Apache 2.0 license as described in the file LICENSE.
Authors: Scott Armstrong, Zohar Komargodski
-/
module

public import KAM.CertificateSharp.Packed.Bridge

/-!
# V2-PACKED gate probe `%s` (opt-in, not built)

%s

Generated by `scripts/packed/gate_gen.py`. Run alone:
`scripts/packed/run_probe.sh 4G $V2P_GATE_DIR/%s.lean LOGDIR`.
-/

@[expose] public section

namespace KAM.CertificateSharp.Packed.Gate.%s

open KAM KAM.Certificate KAM.CertificateSharp.Packed

"""


def wrap_doc(doc, width=100):
    words, lines, cur = doc.split(), [], ""
    for wd in words:
        if cur and len(cur) + 1 + len(wd) > width:
            lines.append(cur)
            cur = wd
        else:
            cur = (cur + " " + wd) if cur else wd
    if cur:
        lines.append(cur)
    return "\n".join(lines)


def write_probe(tag, name, doc, data, stmt):
    full = tag + name
    txt = HEADER % (full, wrap_doc(doc), full, full) + "".join(data)
    txt += "\nset_option profiler true\nset_option profiler.threshold 1\n\n"
    txt += "theorem probe :\n    %s := by\n  decide +kernel\n\nend KAM.CertificateSharp.Packed.Gate.%s\n" % (stmt, full)
    for ln in txt.split("\n"):
        assert len(ln) <= 100, (full, ln[:60], len(ln))
    with open(os.path.join(OUT, full + ".lean"), "w") as f:
        f.write(txt)
    return len(txt.encode())


def compute_probes():
    """GMP-resident compute without literals at LG00's largest product size: factors of 10,127 and 9,185 slots at
    width 264 (every slot 2^124 - k) built in the kernel by `periodic`, one multiplication, advice-free rounding,
    the load check of the 19,311-slot result; once (`C19kCompute`) and ten times (`C19kCompute10`)."""
    os.makedirs(OUT, exist_ok=True)
    one = ("loadOk 264 19311 %d (gmpRound 264 19311 262 %d\n"
           "      ((periodic 264 10127 (2 ^ 124 - 1) : ℤ) *\n"
           "        (periodic 264 9185 (2 ^ 124 - %d) : ℤ)))")
    write_probe("C19k", "Compute", "GMP-resident compute without literals: one product of LG00's largest size "
                "(operands built in the kernel), rounding, load check.", [], (one % (105, 159, 1)) + " = true")
    ten = "(" + " &&\n      ".join(one % (114, sh, k) for k, sh in zip(range(1, 11), range(150, 160))) + ") = true"
    write_probe("C19k", "Compute10", "GMP-resident compute without literals: ten products of LG00's largest size "
                "(rounding shifts 150 to 159), rounding, load checks.", [], ten)


def main():
    if len(sys.argv) > 1 and sys.argv[1] == "compute":
        compute_probes()
        return
    tag = sys.argv[1] if len(sys.argv) > 1 else "G8k"
    if len(sys.argv) > 6:
        dA = (int(sys.argv[2]), int(sys.argv[3]))
        dB = (int(sys.argv[4]), int(sys.argv[5]))
        rad = int(sys.argv[6])
    else:
        dA, dB, rad = (41, 51), (43, 48), 30
    loA = (-(dA[0] // 2), -(dA[1] // 2))
    loB = (-(dB[0] // 2), -(dB[1] // 2))
    rng = random.Random(20261101)
    x = gen_terms(rng, loA, dA, rad)
    y = gen_terms(rng, loB, dB, rad)
    eng = SP.PackedEngine({})
    adv, info = eng.build_real(x, y, W, P, F(1, 2 ** 70))
    da, db = SP.dense(adv.la, x), SP.dense(adv.lb, y)
    assert SP.checkPackedProduct(adv, da, db), "landed mirror check failed"
    T = SP.targetTerms(adv)
    E = SP.remainderBound(adv, W, P2)
    # the packed route
    w = adv.la.width
    Na, Nb = len(da), len(db)
    N = Na + Nb - 1
    ba, bb = max(abs(v) for v in da), max(abs(v) for v in db)
    l = (min(Na, Nb) * ba * bb - 1).bit_length()
    if l + 2 > w:
        w = l + 2
    la = SP.Layout(adv.la.lo, adv.la.dims, adv.la.stride, w, adv.la.blockRows)
    lb = SP.Layout(adv.lb.lo, adv.lb.dims, adv.lb.stride, w, adv.lb.blockRows)
    dcap = deg_cap(la, lb, N)
    s = 1
    while s + 1 <= l and gmp_rem(N, s + 1, dcap) <= E:
        s += 1
    Za, Zb = pack_sum(w, da), pack_sum(w, db)
    conv = [sum(da[i] * db[k - i] for i in range(max(0, k - Nb + 1), min(k, Na - 1) + 1)) for k in range(N)]
    assert Za * Zb == pack_sum(w, conv)
    assert max(abs(c) for c in conv) <= 2 ** l
    rs = [(c + 2 ** (s - 1)) >> s for c in conv]
    R = gmp_round(w, N, l, s, Za * Zb)
    assert R == pack_sum(w, rs), "gmpRound mirror disagrees with slotwise rounding"
    T2 = [(SP.prodKey(la, lb, i), r) for i, r in enumerate(rs) if r != 0]
    E2 = gmp_rem(N, s, dcap)
    os.makedirs(OUT, exist_ok=True)
    # data blocks
    d_x = lean_terms("gx", x)
    d_y = lean_terms("gy", y)
    d_w = "noncomputable def gW : CertWeight := ⟨1 / 100, 107 / 100⟩\n"
    d_win = "".join(lean_int_list("advW%d" % i, r) for i, r in enumerate(adv.rounded))
    d_adv = ("noncomputable def adv : PackedAdvice where\n  la := %s\n  lb := %s\n  target := %s\n"
             "  scale := %d\n  outLog := %d\n  rounded := [%s]\n" % (
                 lean_layout(adv.la), lean_layout(adv.lb), lean_layout(adv.target), adv.scale, adv.outLog,
                 ", ".join("advW%d" % i for i in range(len(adv.rounded)))))
    d_advnw = ("noncomputable def adv : PackedAdvice where\n  la := %s\n  lb := %s\n  target := %s\n"
               "  scale := %d\n  outLog := %d\n  rounded := []\n" % (
                   lean_layout(adv.la), lean_layout(adv.lb), lean_layout(adv.target), adv.scale, adv.outLog))
    d_T = lean_terms("gT", T)
    d_E = "noncomputable def gE : ℚ := %s\n" % lean_rat(E)
    d_g = ("noncomputable def gs : GmpSpec where\n  la := %s\n  lb := %s\n  ba := %d\n  bb := %d\n"
           "  l := %d\n  s := %d\n" % (lean_layout(la), lean_layout(lb), ba, bb, l, s))
    d_Za, ch_a = lean_int_big("gZa", Za)
    d_Zb, ch_b = lean_int_big("gZb", Zb)
    d_R, ch_r = lean_int_big("gR", R)
    d_T2 = lean_terms("gT2", T2)
    d_E2 = "noncomputable def gE2 : ℚ := %s\n" % lean_rat(E2)
    ea = "(adv.la.slotTerms gx)"
    eb = "(adv.lb.slotTerms gy)"
    shard = ("checkShardSp adv\n"
             "      (spBlocks adv.blockLen (adv.spCount adv.la.denseLen) 0 %s)\n"
             "      (spBlocks adv.blockLen (adv.spCount adv.lb.denseLen) 0 %s)\n"
             "      (spMax %s) (spMax %s) %%d = true" % (ea, eb, ea, eb))
    prefix = ("(adv.la.allSlots gx && adv.lb.allSlots gy && adv.shapeOK &&\n"
              "      decide (0 < adv.la.denseLen) && decide (0 < adv.lb.denseLen) &&\n"
              "      packStrictAsc %s && packStrictAsc %s &&\n"
              "      (%s.all fun e => decide (e.1 < adv.la.denseLen)) &&\n"
              "      (%s.all fun e => decide (e.1 < adv.lb.denseLen)) &&\n"
              "      adv.rounded.length ==\n"
              "        adv.spCount adv.la.denseLen + adv.spCount adv.lb.denseLen - 1)\n"
              "      = true" % (ea, eb, ea, eb))
    size = {}
    land = [FORMAT, d_x, d_y, d_win, d_adv]
    size["Ctl"] = write_probe(tag, "Ctl", "Import-only control.", [], "True")
    size["DataL"] = write_probe(tag, "DataL", "Data-only control of the landed probes (factors and advice).",
                                land, "True")
    size["DataP"] = write_probe(tag, "DataP", "Data-only control of the GMP-resident probe (three literals).",
                                [d_Za, d_Zb, d_R], "True")
    for sh in range(len(adv.rounded)):
        size["Lshard%d" % sh] = write_probe(tag, "Lshard%d" % sh, "Landed: one shard of `checkPackedSp`.", land,
                                            shard % sh)
    size["Lprefix"] = write_probe(tag, "Lprefix", "Landed: the non-shard part of `packedRealProduct`'s sparse "
                                  "branch (`allSlots`, `shapeOK` with the advice-zero walk, ordering).", land, prefix)
    size["Ldecode"] = write_probe(tag, "Ldecode", "Landed: the decode `targetTerms` of the advice.",
                                  [FORMAT, d_win, d_adv, d_T], "adv.targetTerms = gT")
    for K in (1500, 3000):
        size["Ldecode%d" % K] = write_probe(tag, "Ldecode%d" % K, "Landed: the first %d terms of the decode "
                                            "`targetTerms` (the one-piece decode exceeds the 4 GB cap)." % K,
                                            [FORMAT, d_win, d_adv, d_T], "adv.targetTerms.take %d = gT.take %d" % (K, K))
    size["Lrem"] = write_probe(tag, "Lrem", "Landed: the remainder `remainderBound` (per product slot).",
                               [d_w, d_advnw, d_E], "adv.remainderBound gW 256 = gE")
    size["Lall"] = write_probe(tag, "Lall", "Landed: the whole real product `packedRealProduct = some (T, e)`.",
                               land + [d_w, d_T, d_E],
                               "packedRealProduct adv gW 256 gx gy = some (gT, gE)")
    size["Pcore"] = write_probe(tag, "Pcore", "GMP-resident: guard, one multiplication, advice-free rounding, "
                                "equality with the packed output literal.", [d_g, d_Za, d_Zb, d_R],
                                "(gs.guard && decide (gs.round gZa gZb = gR)) = true")
    size["Pingest"] = write_probe(tag, "Pingest", "GMP-resident: ingestion of the three packed literals only.",
                                  [d_Za, d_Zb, d_R],
                                  "decide (0 < gZa.natAbs + gZb.natAbs + gR.natAbs) = true")
    size["Ppack"] = write_probe(tag, "Ppack", "Packed route, list boundary: `packRepOk` and `packOf` of both "
                                "factors.", [FORMAT, d_x, d_y, d_g, d_Za, d_Zb],
                                "(packRepOk gs.la gx gs.ba && packRepOk gs.lb gy gs.bb &&\n"
                                "      decide (packOf gs.la gx = gZa) && decide (packOf gs.lb gy = gZb)) = true")
    size["Pdecode"] = write_probe(tag, "Pdecode", "Packed route, list boundary: read-back `GmpSpec.terms`.",
                                  [FORMAT, d_g, d_R, d_T2], "gs.terms gR = gT2")
    size["Prem"] = write_probe(tag, "Prem", "Packed route: the a-priori remainder.", [d_w, d_g, d_E2],
                               "gs.rem gW 256 = gE2")
    size["Pall"] = write_probe(tag, "Pall", "Packed route from lists to lists: `gmpRealProduct = some (T, e)` "
                               "(landed signature).", [FORMAT, d_x, d_y, d_w, d_g, d_T2, d_E2],
                               "gmpRealProduct gs gW 256 gx gy = some (gT2, gE2)")
    meta = dict(tag=tag, dimsA=dA, dimsB=dB, radius=rad, P=P, termsA=len(x), termsB=len(y), denseA=Na, denseB=Nb,
                prodLen=N, landed=dict(width=adv.la.width, blockLen=SP.blockLen(adv), shards=len(adv.rounded),
                                       scale=adv.scale, outLog=adv.outLog, target=[list(adv.target.lo),
                                                                                   list(adv.target.dims)],
                                       advice_slots=sum(len(r) for r in adv.rounded),
                                       advice_nonzero=sum(1 for r in adv.rounded for c in r if c),
                                       out_terms=len(T), rem_log2=math.log2(E) if E else None),
                packed=dict(width=w, l=l, s=s, ba_bits=ba.bit_length(), bb_bits=bb.bit_length(), degCap=dcap,
                            out_terms=len(T2), rem_log2=math.log2(E2), chunks=[ch_a, ch_b, ch_r],
                            bits=[Za.bit_length(), Zb.bit_length(), R.bit_length()]),
                literal_bytes=dict(advice_windows=len(d_win.encode()), landed_terms=len(d_T.encode()),
                                   packed_R=len(d_R.encode()), packed_terms=len(d_T2.encode()),
                                   Za=len(d_Za.encode()), Zb=len(d_Zb.encode()), x=len(d_x.encode()),
                                   y=len(d_y.encode())),
                probe_bytes=size)
    with open(os.path.join(OUT, tag + ".json"), "w") as f:
        json.dump(meta, f, indent=1)
    print(json.dumps(meta, indent=1))


if __name__ == "__main__":
    main()
